fn sub_plan(self:&EpicHuntAndBattlePlan, version, rnd, player, data, goal_data, _debug) -> SubPlan

// L29  챔피언 획득
team = player.info.team                       // PlayerState+0x930, 2 미만이어야 함(아니면 bounds panic)
pos  = player.info.position.as_index()        // PlayerState+0x9c0 → 0..4
champ = data.cache.player_champion[team][pos].unwrap()   // AbstractGameWithCache+0x1e0, None 이면 패닉

// L31  HP 비율(정수 백분율)
hp_ratio = champ.hp * 100 / champ.stat_cached.hp        // Entity+0x670 / +0x628, 분모 0 이면 패닉

// L32  에픽 몬스터 엔티티 (없을 수 있음)
game = data.cache.game                        // dyn AbstractGame
moba = game.vt[0x40]().as_moba().unwrap()     // Moba 모드가 아니면 패닉
epic: Option<&Entity> =
     moba.jungle_runner.epic.live_list.first()   // len==0 → None
         .and_then(|id| game.vt[0x1f0](*id))     // id→엔티티 조회(자체가 Option)

// L33  아군 진영 분수(회복) 사각영역
(lx, ly, rx, ry) = data.context.map.fountains[team]      // MapDef+0x6d70 + team*32

// L34  분수 안인가 (x 먼저, 참일 때만 y 로드)
is_in_heal_area = (champ.x >= lx && champ.x <= rx) && (champ.y >= ly && champ.y <= ry)

// L35  아이템 업그레이드 가능?
can_upgrade_item = game_ai::upgrade_item(version, rnd, player, game.data, game.vtable, data.context).is_some()
                   // 반환은 Option<(usize,usize)> (24B). tag != 0 이면 true

// L36  ① 귀환 판정  — 에픽이 '무손상(풀피)' 일 때만 본다
if epic.is_some_and(|e| e.hp == e.stat_cached.hp)
   && ( hp_ratio < 51
        || can_upgrade_item
        || (champ.hp < champ.stat_cached.hp && is_in_heal_area) )
{
    return SubPlan::Recall(RecallSubPlan)      // tag 5, 페이로드 없음(유닛 구조체)
}

// L41  ② 잠복 판정
if ( goal_data.epic.epic_ally_tick + data.context.setting.tick_per_second
       > goal_data.epic.epic_ally_killed_tick )
   && self.target_bush.is_some()
{
    // L42~43
    let target_bush = self.target_bush.unwrap()
    return SubPlan::Hide(HideSubPlan{
        bush: target_bush,
        out_line: AroundBushOutlineType::Outline,   // 1
        check_move: false,
        enemy_spotted_me: false,
    })                                         // tag 9
}

// L47  ③ 그 외 — 에픽 사냥
return SubPlan::EpicHunt(EpicHuntSubPlan{ need_recall: false })   // tag 11

[IR 분기 순서 메모]
- 블록 82 에서 epic==null 이면 곧장 L41 블록(99)으로 간다. 즉 에픽 엔티티가 없으면 Recall 은 절대 안 나온다.
- 블록 87 에서 epic.hp != epic.max_hp 이면 역시 L41 로. 즉 '에픽이 이미 맞은 상태'면 귀환 안 하고 계속 붙는다.
- 귀환 조건 3항의 IR 결합 순서는 %95=(hp_ratio<51 || can_upgrade_item), %97=(hp<max && in_heal_area), %98=%97||%95 로
  or 이 재결합돼 있으나 전부 부작용 없는 값이라 소스 순서와 결과는 동일하다.
- upgrade_item 은 L35 에서 **무조건** 호출된다(조건부 호출이 아님). 부작용이 있는 함수라면 호출 자체가 관측 대상.
